ALTER TABLE public.products ADD COLUMN tax_bps integer, ADD COLUMN tax_inclusive boolean NOT NULL DEFAULT true, ADD COLUMN return_days integer NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN address_snapshot jsonb, ADD COLUMN subtotal_paise integer NOT NULL DEFAULT 0, ADD COLUMN discount_paise integer NOT NULL DEFAULT 0, ADD COLUMN shipping_paise integer NOT NULL DEFAULT 0, ADD COLUMN tax_paise integer NOT NULL DEFAULT 0, ADD COLUMN idempotency_key uuid, ADD COLUMN reservation_expires_at timestamptz, ADD COLUMN delivered_at timestamptz;
CREATE UNIQUE INDEX orders_idempotency ON public.orders(user_id,idempotency_key);
CREATE TABLE public.shipping_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pincode text UNIQUE NOT NULL CHECK(pincode ~ '^[1-9][0-9]{5}$'), fee_paise integer NOT NULL CHECK(fee_paise>=0), min_days integer NOT NULL CHECK(min_days>=0), max_days integer NOT NULL CHECK(max_days>=min_days), active boolean NOT NULL DEFAULT false, cod_enabled boolean NOT NULL DEFAULT false);
GRANT ALL ON public.shipping_rules TO service_role; GRANT SELECT,INSERT,UPDATE ON public.shipping_rules TO authenticated;
ALTER TABLE public.shipping_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_shipping ON public.shipping_rules FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','operations']));
CREATE TABLE public.coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, percent integer NOT NULL CHECK(percent BETWEEN 1 AND 100), min_subtotal_paise integer NOT NULL DEFAULT 0 CHECK(min_subtotal_paise>=0), max_discount_paise integer NOT NULL CHECK(max_discount_paise>0), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT false);
GRANT ALL ON public.coupons TO service_role; GRANT SELECT,INSERT,UPDATE ON public.coupons TO authenticated;
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_coupons ON public.coupons FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','catalogue'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','catalogue']));
CREATE TABLE public.order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), product_id text NOT NULL REFERENCES public.products(id), name text NOT NULL, sku text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), unit_price_paise integer NOT NULL, tax_bps integer NOT NULL, return_days integer NOT NULL DEFAULT 0, fulfillment_model text NOT NULL, UNIQUE(order_id,product_id));
GRANT SELECT ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_order_items ON public.order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND o.user_id=auth.uid()));
CREATE POLICY staff_order_items ON public.order_items FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','support']));
CREATE TABLE public.fulfillments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), item_id uuid UNIQUE NOT NULL REFERENCES public.order_items(id), supplier_id uuid REFERENCES public.suppliers(id), status text NOT NULL DEFAULT 'awaiting_payment', carrier text, tracking_number text, tracking_url text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.fulfillments TO authenticated; GRANT ALL ON public.fulfillments TO service_role;
ALTER TABLE public.fulfillments ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_fulfillments ON public.fulfillments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND o.user_id=auth.uid()));
CREATE POLICY staff_fulfillments ON public.fulfillments FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','support']));
CREATE TABLE public.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid UNIQUE NOT NULL REFERENCES public.orders(id), provider_order_id text UNIQUE NOT NULL, provider_payment_id text UNIQUE, amount_paise integer NOT NULL CHECK(amount_paise>0), status text NOT NULL DEFAULT 'pending');
GRANT SELECT ON public.payments TO authenticated; GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_payments ON public.payments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND o.user_id=auth.uid()));
CREATE POLICY staff_payments ON public.payments FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','support']));
CREATE TABLE public.payment_webhook_events(id text PRIMARY KEY, event_type text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), result text NOT NULL);
GRANT ALL ON public.payment_webhook_events TO service_role;
ALTER TABLE public.payment_webhook_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.inventory_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id text NOT NULL REFERENCES public.products(id), delta integer NOT NULL, reason text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.inventory_movements TO authenticated; GRANT ALL ON public.inventory_movements TO service_role;
ALTER TABLE public.inventory_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_movements ON public.inventory_movements FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','catalogue']));
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit ON public.audit_logs FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin']));
CREATE TABLE public.order_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), user_id uuid NOT NULL REFERENCES public.profiles(id), kind text NOT NULL CHECK(kind IN ('cancellation','return')), reason text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','rejected','completed')), staff_note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,kind));
GRANT SELECT ON public.order_requests TO authenticated; GRANT ALL ON public.order_requests TO service_role;
ALTER TABLE public.order_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_requests ON public.order_requests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY staff_requests ON public.order_requests FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','support']));
CREATE TABLE public.account_deletion_requests(user_id uuid PRIMARY KEY REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'requested', requested_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.account_deletion_requests TO authenticated; GRANT ALL ON public.account_deletion_requests TO service_role;
ALTER TABLE public.account_deletion_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_deletion_read ON public.account_deletion_requests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_deletion_request ON public.account_deletion_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='requested');
CREATE OR REPLACE FUNCTION public.audit_staff_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),TG_TABLE_NAME||':'||TG_OP,coalesce(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'product_id','unknown'),jsonb_build_object('before',to_jsonb(OLD),'after',to_jsonb(NEW))); RETURN NEW; END $$;
CREATE TRIGGER audit_products AFTER INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.audit_staff_change();
CREATE TRIGGER audit_categories AFTER INSERT OR UPDATE ON public.categories FOR EACH ROW EXECUTE FUNCTION public.audit_staff_change();
CREATE TRIGGER audit_suppliers AFTER INSERT OR UPDATE ON public.suppliers FOR EACH ROW EXECUTE FUNCTION public.audit_staff_change();
CREATE TRIGGER audit_supplier_products AFTER INSERT OR UPDATE ON public.supplier_products FOR EACH ROW EXECUTE FUNCTION public.audit_staff_change();
CREATE TRIGGER audit_shipping AFTER INSERT OR UPDATE ON public.shipping_rules FOR EACH ROW EXECUTE FUNCTION public.audit_staff_change();
CREATE TRIGGER audit_coupons AFTER INSERT OR UPDATE ON public.coupons FOR EACH ROW EXECUTE FUNCTION public.audit_staff_change();
CREATE OR REPLACE FUNCTION public.adjust_inventory(_product text,_delta integer,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.staff_has_role(ARRAY['owner','admin','operations','catalogue']) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _delta=0 OR length(trim(_reason))<3 THEN RAISE EXCEPTION 'Adjustment reason required'; END IF; INSERT INTO public.inventory(product_id,quantity,reserved) VALUES(_product,0,0) ON CONFLICT DO NOTHING; UPDATE public.inventory SET quantity=quantity+_delta WHERE product_id=_product AND quantity+_delta>=reserved AND quantity+_delta>=0; IF NOT FOUND THEN RAISE EXCEPTION 'Adjustment exceeds available stock'; END IF; INSERT INTO public.inventory_movements(product_id,delta,reason,actor_id) VALUES(_product,_delta,_reason,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.adjust_inventory(text,integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.adjust_inventory(text,integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.request_order_action(_order uuid,_kind text,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; r uuid; BEGIN SELECT * INTO o FROM public.orders WHERE id=_order AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order unavailable'; END IF; IF length(trim(_reason))<5 OR length(_reason)>1000 THEN RAISE EXCEPTION 'Reason must be 5 to 1000 characters'; END IF; IF _kind='cancellation' THEN IF o.status NOT IN ('pending_payment','confirmed','processing','awaiting_supplier_fulfillment') THEN RAISE EXCEPTION 'Cancellation is not available'; END IF; ELSIF _kind='return' THEN IF o.status<>'delivered' OR o.delivered_at IS NULL OR NOT EXISTS(SELECT 1 FROM public.order_items WHERE order_id=o.id AND return_days>0 AND now()<=o.delivered_at+make_interval(days=>return_days)) THEN RAISE EXCEPTION 'Return window is not available'; END IF; ELSE RAISE EXCEPTION 'Invalid request'; END IF; INSERT INTO public.order_requests(order_id,user_id,kind,reason) VALUES(o.id,auth.uid(),_kind,_reason) RETURNING id INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.request_order_action(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_order_action(uuid,text,text) TO authenticated;